This piece of code must ensure that the file path requested belongs to any of the user projects by checking if they start with any abs_project_path, if not it will be considered a current project file and surrect abs_project path will be prepended to it:



```python

def get_valid_project_file_path(self, file_path: str):
        abs_project_path = self.settings.abs_project_path
        abs_file_path = file_path
        file_exsists = os.path.isfile(abs_file_path)
        is_project_file = abs_file_path.startswith(abs_project_path)


        # File belongs to the project
        if file_exsists and is_project_file:
            return abs_file_path
        
        # New project's file 
        if not file_exsists:
            return os.path.normpath(os.path.join(abs_project_path, abs_file_path))


        # Check if project belongs to any user's project
        for project in find_all_user_projects(self.user):
            if abs_file_path.startswith(project.abs_project_path):
                return abs_file_path
        
        return None
```
